    styleTitre: (s) => `Serate ${s} in Costa Azzurra: Nizza, Cannes, Monaco · Teufy`, styleH1: (s) => `Serate <em>${s}</em> in Costa Azzurra`, styleDesc: (s, n) => `Tutte le serate ${s} di Nizza, Cannes, Monaco e Antibes: ${n} serate in arrivo con orari, prezzi e biglietti. Aggiornato ogni giorno.`, styleEtiquette: 'Stile',
    festTitre: 'Festival in Costa Azzurra: l’estate a Nizza, Cannes, Monaco · Teufy', festDesc: 'I festival della Costa Azzurra: prossime date e guida ai festival estivi (Nice Jazz Festival, Jazz à Juan, Nuits du Sud…) e ai grandi appuntamenti dell’anno.', festH1: 'I <em>festival</em> della Costa Azzurra', festP: 'I prossimi festival della guida, i festival estivi e i grandi appuntamenti dell’anno sulla Costa.', festAgendaH2: 'Prossimamente nella <em>guida</em>', festAgendaVide: 'Nessun festival nella guida per le prossime settimane: tornano con la bella stagione.', festGuideH2: 'I festival dell’<em>estate</em>', festRdvH2: 'I grandi appuntamenti dell’<em>anno</em>', festAvert: 'Le date cambiano ogni anno: vengono aggiunte alla guida appena sono ufficiali. Controlla sempre il sito ufficiale.', siteOfficiel: 'Sito ufficiale',
